generata:
db.macchinari.aggregate([
  {
    $unwind: "$log_manutenzione"
  },
  {
    $project: {
      _id: 1,
      codice_modello: 1,
      anno_costruzione: 1,
      ore_operative: 1,
      stato: 1,
      automatizzato: 1,
      tecnico: "$log_manutenzione.tecnico",
      costo: "$log_manutenzione.costo"
    }
  }
])

db.subscriptions.aggregate([
  {
    $match: {
      "features": {
        $elemMatch: {
          "name": "Streaming"
        }
      }
    }
  },
  {
    $project: {
      _id: 1,
      plan_name: 1,
      price: 1,
      data_limit: 1,
      unlimited_calls: 1,
      features: {
        $filter: {
          input: "$features",
          as: "feature",
          cond: {
            $eq: ["$$feature.name", "Streaming"]
          }
        }
      }
    }
  }
])

db.spedizioni.aggregate([
  {
    $unwind: "$righe"
  },
  {
    $lookup: {
      from: "ispettori",
      localField: "righe.id_ispettori",
      foreignField: "_id",
      as: "ispettore"
    }
  },
  {
    $unwind: "$ispettore"
  },
  {
    $project: {
      _id: 1,
      peso_kg: 1,
      stato: 1,
      sdoganata: 1,
      contenuto: 1,
      dimensioni_collo: 1,
      righe: 1,
      ispettore: {
        _id: 1,
        nome: 1,
        livello: 1,
        anni_esperienza: 1,
        disponibile: 1,
        contatto: {
          email: 1,
          interno: 1
        }
      }
    }
  }
])

db.createView('vista_combinata', ['arnia', 'macchinari'], [
  {
    $project: {
      _id: 1,
      nome: {
        $cond: [
          { $eq: ['$codice_arnia', 'B02'] },
          '$codice_arnia',
          '$codice_modello'
        ]
      },
      peso: 1,
      stato: 1,
      automatizzato: 1,
      ore_operative: 1
    }
  }
])

db.stabilimenti.aggregate([
  {
    $lookup: {
      from: "macchinari",
      localField: "id_macchinari",
      foreignField: "_id",
      as: "macchinari"
    }
  },
  {
    $unwind: "$macchinari"
  },
  {
    $project: {
      _id: 1,
      nome_stabilimento: 1,
      superficie: 1,
      numero_dipendenti: 1,
      mensa_presente: 1,
      zona_regionale: 1,
      id_macchinari: 1,
      macchinari: {
        _id: 1,
        codice_modello: 1,
        anno_costruzione: 1,
        ore_operative: 1,
        stato: 1,
        automatizzato: 1
      }
    }
  }
])

db.percorsi_raccolta.aggregate([
  {
    $match: {
      numero_fermate: { $lte: 32 },
      distanza_km: 118.9
    }
  },
  {
    $lookup: {
      from: "cassonetti",
      localField: "_id",
      foreignField: "id_percorsi_raccolta",
      as: "cassonetti"
    }
  },
  {
    $unwind: "$cassonetti"
  },
  {
    $group: {
      _id: "$_id",
      numero_fermate: { $first: "$numero_fermate" },
      distanza_km: { $first: "$distanza_km" },
      cassonetti: { $push: "$cassonetti" }
    }
  },
  {
    $project: {
      _id: 1,
      numero_fermate: 1,
      distanza_km: 1,
      cassonetti: 1
    }
  }
])

db.missions.aggregate([
  {
    $match: {
      critical: true,
      departure: "Genova"
    }
  },
  {
    $lookup: {
      from: "voyages",
      localField: "voyage_id",
      foreignField: "_id",
      as: "voyage"
    }
  },
  {
    $unwind: "$voyage"
  },
  {
    $match: {
      "voyage.is_delayed": true
    }
  },
  {
    $project: {
      _id: 1,
      departure: 1,
      duration_days: 1,
      fuel_consumed: 1,
      is_delayed: 1,
      route_points: 1,
      cargo_details: 1
    }
  }
])

db.missions.aggregate([
  {
    $match: {
      "is_delayed": true,
      "departure": "Genova"
    }
  },
  {
    $lookup: {
      from: "voyages",
      localField: "voyage_id",
      foreignField: "_id",
      as: "voyage"
    }
  },
  {
    $unwind: "$voyage"
  },
  {
    $project: {
      _id: 1,
      voyage_id: 1,
      departure: "$voyage.departure",
      is_delayed: 1
    }
  },
  {
    $group: {
      _id: "$voyage_id",
      count: { $sum: 1 }
    }
  }
])

db.missions.aggregate([
  {
    $match: {
      critical: true
    }
  },
  {
    $lookup: {
      from: "voyages",
      localField: "voyage_id",
      foreignField: "_id",
      as: "voyage"
    }
  },
  {
    $unwind: "$voyage"
  },
  {
    $match: {
      "voyage.is_delayed": true
    }
  },
  {
    $group: {
      _id: "$voyage._id",
      mission_id: "$_id",
      voyage_id: "$voyage_id",
      critical: "$critical",
      tasks: "$tasks",
      destination: "$destination",
      budget: "$budget",
      duration_days: "$duration_days"
    }
  },
  {
    $group: {
      _id: "$_id",
      mission_id: { $push: "$mission_id" },
      voyage_id: { $push: "$voyage_id" },
      critical: { $push: "$critical" },
      tasks: { $push: "$tasks" },
      destination: { $push: "$destination" },
      budget: { $push: "$budget" },
      duration_days: { $push: "$duration_days" }
    }
  }
])

db.equipments.aggregate([
  {
    $match: {
      $or: [
        { "storage_location": "laboratorio" },
        { "history.year": { $gte: 2021, $lte: 2024 } }
      ]
    }
  },
  {
    $lookup: {
      from: "experiments",
      localField: "items.equipment_id",
      foreignField: "_id",
      as: "experiments"
    }
  },
  {
    $unwind: "$experiments"
  },
  {
    $group: {
      _id: "$_id",
      items: { $addToSet: "$items" }
    }
  },
  {
    $project: {
      _id: 1,
      items: 1
    }
  }
])

db.veicoli.aggregate([
  {
    $match: {
      motore: { $ne: "Diesel" },
      km_manutenzione: { $ne: 460607 }
    }
  },
  {
    $group: {
      _id: "$_id",
      targa: { $first: "$targa" },
      capacita_ton: { $first: "$capacita_ton" },
      motore: { $first: "$motore" },
      km_manutenzione: { $first: "$km_manutenzione" },
      fermate_rotta: { $first: "$fermate_rotta" },
      dimensioni: { $first: "$dimensioni" }
    }
  }
])

db.missions.aggregate([
  {
    $match: {
      $or: [
        { critical: true },
        { is_delayed: true }
      ]
    }
  },
  {
    $group: {
      _id: "$voyage_id",
      voyage_id: "$voyage_id",
      departure: { $first: "$departure" },
      duration_days: { $first: "$duration_days" },
      fuel_consumed: { $first: "$fuel_consumed" },
      is_delayed: { $first: "$is_delayed" },
      route_points: { $first: "$route_points" },
      cargo_details: { $first: "$cargo_details" }
    }
  },
  {
    $project: {
      _id: 0,
      voyage_id: 1,
      departure: 1,
      duration_days: 1,
      fuel_consumed: 1,
      is_delayed: 1,
      route_points: 1,
      cargo_details: 1
    }
  }
])

db.veicoli.aggregate([
  {
    $match: {
      km_manutenzione: { $ne: 272059 },
      "dimensioni.larghezza": { $gt: 2.1, $lt: 3.6 }
    }
  },
  {
    $group: {
      _id: "$_id",
      targa: "$targa",
      capacita_ton: "$capacita_ton",
      motore: "$motore",
      km_manutenzione: "$km_manutenzione",
      fermate_rotta: "$fermate_rotta",
      dimensioni: "$dimensioni"
    }
  }
])

db.missions.aggregate([
  {
    $match: {
      "voyage_id": {
        $in: db.voyages.distinct("_id", { "fuel_consumed": { $gte: 47.0 } })
      }
    }
  },
  {
    $lookup: {
      from: "voyages",
      localField: "voyage_id",
      foreignField: "_id",
      as: "voyage"
    }
  },
  {
    $unwind: "$voyage"
  },
  {
    $match: {
      "voyage.departure": "Genova"
    }
  },
  {
    $group: {
      _id: "$_id",
      voyage_id: { $first: "$voyage_id" },
      destination: { $first: "$destination" },
      duration_days: { $first: "$duration_days" },
      budget: { $first: "$budget" },
      critical: { $first: "$critical" },
      tasks: { $first: "$tasks" },
      fuel_consumed: { $first: "$fuel_consumed" },
      is_delayed: { $first: "$is_delayed" },
      route_points: { $first: "$route_points" },
      cargo_details: { $first: "$cargo_details" }
    }
  },
  {
    $project: {
      _id: 1,
      voyage_id: 1,
      destination: 1,
      duration_days: 1,
      budget: 1,
      critical: 1,
      tasks: 1,
      fuel_consumed: 1,
      is_delayed: 1,
      route_points: 1,
      cargo_details: 1
    }
  }
])

db.missions.aggregate([
  {
    $lookup: {
      from: "voyages",
      localField: "voyage_id",
      foreignField: "_id",
      as: "voyage"
    }
  },
  {
    $match: {
      "voyage.cargo_details.weight": { $gte: 47.0 },
      "voyage.departure": "Genova"
    }
  },
  {
    $group: {
      _id: "$_id",
      voyage_id: { $first: "$voyage_id" },
      destination: { $first: "$destination" },
      duration_days: { $first: "$duration_days" },
      budget: { $first: "$budget" },
      critical: { $first: "$critical" },
      tasks: { $first: "$tasks" },
      voyage: { $push: "$voyage" }
    }
  },
  {
    $project: {
      _id: 1,
      voyage_id: 1,
      destination: 1,
      duration_days: 1,
      budget: 1,
      critical: 1,
      tasks: 1,
      voyage: 1
    }
  }
])

db.veicoli.aggregate([
  {
    $match: {
      $or: [
        { "dimensioni.altezza": { $ne: 3.2 } },
        { "km_manutenzione": { $gte: 205255 } }
      ]
    }
  },
  {
    $group: {
      _id: "$_id",
      id_veicoli: { $first: "$id_veicoli" },
      targa: { $first: "$targa" },
      capacita_ton: { $first: "$capacita_ton" },
      motore: { $first: "$motore" },
      km_manutenzione: { $first: "$km_manutenzione" },
      fermate_rotta: { $first: "$fermate_rotta" },
      dimensioni: { $first: "$dimensioni" }
    }
  },
  {
    $project: {
      _id: 1,
      id_veicoli: 1,
      targa: 1,
      capacita_ton: 1,
      motore: 1,
      km_manutenzione: 1,
      fermate_rotta: 1,
      dimensioni: 1
    }
  }
])

db.cases.aggregate([
  {
    $match: {
      $or: [
        { dossier_id: { $ne: "F-2023-02" } },
        { year: { $gt: 2010, $lt: 2024 } }
      ]
    }
  },
  {
    $group: {
      _id: null,
      cases: { $push: "$$ROOT" }
    }
  },
  {
    $unwind: "$cases"
  },
  {
    $replaceRoot: { newRoot: "$cases" }
  }
])

db.tombe.aggregate([
  {
    $match: {
      $or: [
        { settore: { $ne: "C" } },
        { occupata: true }
      ]
    }
  },
  {
    $group: {
      _id: "$_id",
      settore: { $first: "$settore" },
      occupata: { $first: "$occupata" }
    }
  },
  {
    $project: {
      _id: 1,
      settore: 1,
      occupata: 1
    }
  }
])

db.cases.aggregate([
  {
    $match: {
      dossier_id: "F-2023-02",
      year: { $ne: 2021 },
      is_closed: false
    }
  },
  {
    $group: {
      _id: null,
      count: { $sum: 1 }
    }
  },
  {
    $project: {
      _id: 0,
      count: 1
    }
  },
  {
    $match: {
      count: { $eq: 0 }
    }
  }
])

db.missions.aggregate([
  {
    $match: {
      "is_delayed": false,
      "critical": false
    }
  },
  {
    $group: {
      _id: "$_id",
      voyage_id: { $addToSet: "$voyage_id" }
    }
  },
  {
    $lookup: {
      from: "voyages",
      localField: "voyage_id",
      foreignField: "_id",
      as: "voyage"
    }
  },
  {
    $unwind: "$voyage"
  },
  {
    $match: {
      "voyage.is_delayed": false
    }
  },
  {
    $group: {
      _id: "$_id",
      voyage_id: { $addToSet: "$voyage_id" },
      voyage: { $addToSet: "$voyage" }
    }
  },
  {
    $project: {
      _id: 1,
      voyage_id: 1,
      voyage: 1
    }
  }
])

db.ispettori.aggregate([
  {
    $match: {
      nome: "Giulia",
      anni_esperienza: { $gte: 26 }
    }
  },
  {
    $group: {
      _id: "$_id",
      id_ispettori: { $push: "$_id" }
    }
  },
  {
    $project: {
      _id: 1,
      id_ispettori: 1
    }
  },
  {
    $group: {
      _id: null,
      id_ispettori: { $setDifference: ["$id_ispettori", "$$REMOVE"] }
    }
  },
  {
    $project: {
      _id: 0,
      id_ispettori: 1
    }
  }
])

db.equipments.aggregate([
  {
    $match: {
      storage_location: "deposito A",
      voltage: { $gt: 194 }
    }
  },
  {
    $group: {
      _id: "$_id",
      equipment_id: { $addToSet: "$items.equipment_id" }
    }
  },
  {
    $project: {
      _id: 1,
      equipment_id: 1
    }
  }
])

db.missions.aggregate([
  {
    $match: {
      critical: false
    }
  },
  {
    $lookup: {
      from: "voyages",
      localField: "voyage_id",
      foreignField: "_id",
      as: "voyage"
    }
  },
  {
    $unwind: {
      path: "$voyage"
    }
  },
  {
    $match: {
      "voyage.is_delayed": false
    }
  },
  {
    $group: {
      _id: "$voyage._id",
      id: { $addToSet: "$_id" }
    }
  },
  {
    $project: {
      _id: 1,
      id: 1
    }
  }
])

db.missions.aggregate([
  {
    $match: {
      critical: false
    }
  },
  {
    $lookup: {
      from: "voyages",
      localField: "voyage_id",
      foreignField: "_id",
      as: "voyage"
    }
  },
  {
    $unwind: "$voyage"
  },
  {
    $match: {
      "voyage.is_delayed": false
    }
  },
  {
    $group: {
      _id: null,
      ids: {
        $push: "$_id"
      }
    }
  },
  {
    $project: {
      _id: 0,
      ids: 1
    }
  }
])
